    /// <summary>
    /// Chain of Command; after posting, update records.
    /// </summary>
    protected void endPost()
    {
        next endPost();

        if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METSalesOrderConfirmedBusinessEvent)))
        {
            METSalesOrderConfirmedBusinessEvent::newFromCustConfirmJour(custConfirmJour).send();
        }
    }
